package com.soulsync.web;
import com.soulsync.domain.Enums.*; import com.soulsync.service.AdminService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/admin") @RequiredArgsConstructor
public class AdminController { private final AdminService service; record UserStatusRequest(UserStatus status){} record ReportStatusRequest(ReportStatus status){} @GetMapping("/users")List<AdminService.AdminUserDto> users(){return service.users();}@PatchMapping("/users/{id}/status")AdminService.AdminUserDto status(@PathVariable UUID id,@RequestBody UserStatusRequest r){return service.status(id,r.status());}@GetMapping("/reports")List<AdminService.AdminReportDto> reports(){return service.reports();}@PatchMapping("/reports/{id}/status")AdminService.AdminReportDto report(@PathVariable UUID id,@RequestBody ReportStatusRequest r){return service.reportStatus(id,r.status());}@GetMapping("/audit")List<AdminService.AuditDto> audit(){return service.audits();}}
